-- DAGA V30 foundation schema (Cloudflare D1 / SQLite)
-- Apply only to a dedicated D1 database after review; do not run against production blindly.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS daga_accounts (id TEXT PRIMARY KEY, phone_e164 TEXT, email TEXT, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('program_owner','store_owner','manager','employee')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','suspended')), store_id TEXT, phone_verified_at TEXT, email_verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS daga_accounts_phone_unique ON daga_accounts(phone_e164) WHERE phone_e164 IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS daga_accounts_email_unique ON daga_accounts(email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS daga_accounts_role_status ON daga_accounts(role, status);
CREATE INDEX IF NOT EXISTS daga_accounts_store ON daga_accounts(store_id);
-- Owner is provisioned by a one-time server-side bootstrap, never public registration.
CREATE TABLE IF NOT EXISTS daga_program_owner (singleton_id INTEGER PRIMARY KEY CHECK (singleton_id = 1), account_id TEXT NOT NULL UNIQUE REFERENCES daga_accounts(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_stores (id TEXT PRIMARY KEY, owner_account_id TEXT NOT NULL REFERENCES daga_accounts(id), legal_identity TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','suspended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_plans (id TEXT PRIMARY KEY, service TEXT NOT NULL CHECK (service IN ('store','live_daga')), name TEXT NOT NULL, price_minor INTEGER NOT NULL CHECK (price_minor >= 0), currency TEXT NOT NULL DEFAULT 'EGP', duration_days INTEGER NOT NULL DEFAULT 30 CHECK (duration_days > 0), word_quota INTEGER, features_json TEXT NOT NULL DEFAULT '{}', is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), version INTEGER NOT NULL DEFAULT 1, updated_by TEXT REFERENCES daga_accounts(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_plan_orders (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES daga_accounts(id), store_id TEXT REFERENCES daga_stores(id), plan_id TEXT NOT NULL REFERENCES daga_plans(id), plan_version INTEGER NOT NULL, agreed_price_minor INTEGER NOT NULL CHECK (agreed_price_minor >= 0), currency TEXT NOT NULL DEFAULT 'EGP', status TEXT NOT NULL DEFAULT 'awaiting_payment' CHECK (status IN ('awaiting_payment','payment_submitted','under_review','paid_approved','rejected','cancelled','expired')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_payment_methods (id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK (provider IN ('vodafone_cash','instapay')), display_label TEXT NOT NULL, destination_value TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), updated_by TEXT REFERENCES daga_accounts(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_payment_submissions (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES daga_plan_orders(id), payment_method_id TEXT NOT NULL REFERENCES daga_payment_methods(id), claimed_amount_minor INTEGER NOT NULL CHECK (claimed_amount_minor >= 0), transaction_reference TEXT, receipt_url TEXT, submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by TEXT REFERENCES daga_accounts(id), reviewed_at TEXT, status TEXT NOT NULL DEFAULT 'pending_review' CHECK (status IN ('pending_review','confirmed','rejected')));
CREATE TABLE IF NOT EXISTS daga_entitlements (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES daga_accounts(id), store_id TEXT REFERENCES daga_stores(id), service TEXT NOT NULL CHECK (service IN ('store','live_daga')), order_id TEXT NOT NULL UNIQUE REFERENCES daga_plan_orders(id), starts_at TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','expired','revoked')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daga_live_word_ledger (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES daga_accounts(id), store_id TEXT REFERENCES daga_stores(id), order_id TEXT REFERENCES daga_plan_orders(id), event_type TEXT NOT NULL CHECK (event_type IN ('credit','debit','adjustment','refund')), words INTEGER NOT NULL CHECK (words > 0), request_id TEXT UNIQUE, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS daga_live_ledger_account_time ON daga_live_word_ledger(account_id, created_at);
CREATE TABLE IF NOT EXISTS daga_column_definitions (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK (scope IN ('system_default','store')), store_id TEXT REFERENCES daga_stores(id), stable_key TEXT NOT NULL, display_name TEXT NOT NULL, data_type TEXT NOT NULL, behavior_json TEXT NOT NULL DEFAULT '{}', calculation_key TEXT, is_enabled INTEGER NOT NULL DEFAULT 1 CHECK (is_enabled IN (0,1)), updated_by TEXT REFERENCES daga_accounts(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(scope, store_id, stable_key));
CREATE TABLE IF NOT EXISTS daga_audit_log (id TEXT PRIMARY KEY, actor_account_id TEXT REFERENCES daga_accounts(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS daga_audit_actor_time ON daga_audit_log(actor_account_id, created_at);
